  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // If thresholds are provided, evaluate them
  if (thresholds && typeof thresholds === 'object' && Object.keys(thresholds).length > 0) {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= min;

      if (!passed) {
        allPassed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

/**
 * Writes an evaluation report to disk.
 * @param {Object} config
 * @param {Object} config.report - Report object from generateReport
 * @param {string} config.format - Report format ('json' or 'markdown')
 * @param {string} config.reportPath - Output file path
 * @param {Object} config.fs - Filesystem module (default: fs)
 * @returns {string} Path where report was written
 */
export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

