fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'test'], null, 2));

console.log('\n1. Testing loadDataset...');
const dataset = Eval.loadDataset({
  outputsPath,
  referencesPath
});
console.log('✓ Dataset loaded successfully');
