const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});
console.log('✓ Evaluations run successfully');
evaluations.forEach((metric) => {
  console.log(`  ${metric.id}: ${metric.score ?? 'n/a'} (${metric.label})`);
});

console.log('\n3. Testing generateReport with passing thresholds...');
const reportPass = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});
console.log('✓ Report generated successfully');
console.log(`  Passed: ${reportPass.passed}`);
console.log(`  Thresholds: ${reportPass.thresholds.length} checks`);
reportPass.thresholds.forEach((t) => {
  console.log(`    - ${t.metric}: ${t.passed ? 'PASS' : 'FAIL'} (${t.score ?? 'n/a'} >= ${t.min})`);
});

console.log('\n4. Testing generateReport with failing thresholds...');
const reportFail = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: { exact_match: 0.99 }
});
console.log('✓ Report generated successfully');
console.log(`  Passed: ${reportFail.passed}`);
console.log(`  Thresholds: ${reportFail.thresholds.length} checks`);
reportFail.thresholds.forEach((t) => {
  console.log(`    - ${t.metric}: ${t.passed ? 'PASS' : 'FAIL'} (${t.score ?? 'n/a'} >= ${t.min})`);
});

console.log('\n5. Testing writeReport with thresholds...');
const jsonPath = Eval.writeReport({
  report: reportPass,
  format: 'json',
  reportPath: path.join(tmpDir, 'report.json')
});
const markdownPath = Eval.writeReport({
  report: reportPass,
  format: 'markdown',
  reportPath: path.join(tmpDir, 'report.md')
});
console.log('✓ Reports written successfully');
console.log(`  JSON: ${jsonPath}`);
console.log(`  Markdown: ${markdownPath}`);

// Verify files exist and contain expected content
const jsonContent = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
const markdownContent = fs.readFileSync(markdownPath, 'utf8');

console.log('\n6. Verifying JSON report...');
console.log(`  ✓ Contains 'passed' field: ${jsonContent.passed !== undefined}`);
console.log(`  ✓ Contains 'thresholds' field: ${Array.isArray(jsonContent.thresholds)}`);
console.log(`  ✓ Threshold count: ${jsonContent.thresholds.length}`);

console.log('\n7. Verifying Markdown report...');
console.log(`  ✓ Contains 'Thresholds' section: ${markdownContent.includes('## Thresholds')}`);
console.log(`  ✓ Contains metric names: ${markdownContent.includes('exact_match')}`);
console.log(`  ✓ Contains PASS/FAIL status: ${markdownContent.includes('PASS')}`);

// Clean up
fs.rmSync(tmpDir, { recursive: true, force: true });

console.log('\n✅ All tests passed!');

